const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
async function get(u){const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw Error();return r.json()}
async function render(){const id=new URLSearchParams(location.search).get('id');if(!id){$('#rider-content').innerHTML='<p class="empty">Choose a rider from the live results to view their complete record.</p>';return}try{const rider=await get('/api/public/riders/'+encodeURIComponent(id)),records=rider.records||[],first=records[0]||{},fastest=records.reduce((best,x)=>!best||x.time<best.time?x:best,null);document.title=`${rider.name} · OWAR 2026`;$('#back-results').href=first.tournament?'/?event='+encodeURIComponent(first.tournament.toLowerCase()):'/';$('#rider-content').innerHTML=`<section class="rider-hero"><div class="rider-number">${esc(first.bib||'—')}</div><div><div class="eyebrow">${esc(first.tournament||'Rider')}</div><h1>${esc(rider.name)}</h1><p>Bib ${esc(first.bib||'—')} · ${esc(first.tournament||'OWAR 2026')}</p></div></section><section class="rider-stats"><div><span>Recorded races</span><strong>${records.length}</strong></div><div><span>Fastest time</span><strong>${esc(fastest?.time||'—')}</strong></div></section><section class="race-table history-card"><div class="history-heading"><span>Current event</span><h2>Every recorded time</h2></div><div class="table-scroll"><table class="rider-times"><colgroup><col class="rider-time-stage"><col class="rider-time-race"><col class="rider-time-position"><col class="rider-time-value"></colgroup><thead><tr><th>Stage</th><th>Race</th><th>Position</th><th>Time</th></tr></thead><tbody>${records.map(x=>`<tr><td><span class="history-stage">${esc(x.stage||x.level||'Results')}</span></td><td>${esc(x.race)}</td><td>${esc(x.position)}</td><td class="time">${esc(x.time)}</td></tr>`).join('')||'<tr><td colspan="4">No recorded times yet.</td></tr>'}</tbody></table></div></section>`}catch{$('#rider-content').innerHTML='<p class="empty">This rider record is not available yet.</p>'}}
render();
